import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, sin } from 'three/tsl';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    BoxGeometry,
    MeshBasicMaterial,
    DoubleSide,
  } = THREE;

  const root = new Group();
  const owned = [];
  const timelines = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10',
  };

  const makeBasicMaterial = (params) => {
    const material = new MeshBasicMaterial(params);
    owned.push(material);
    return material;
  };

  const makeNodeMaterial = () => {
    const material = new MeshBasicNodeMaterial();
    owned.push(material);
    return material;
  };

  const backdropMaterial = makeNodeMaterial();
  const backdropUv = uv();
  const lower = vec3(0.0431373, 0.0431373, 0.0627451);
  const upper = vec3(0.0862745, 0.0862745, 0.1137255);
  const gradientMix = smoothstep(0.0, 1.0, backdropUv.y);
  const gradient = mix(lower, upper, gradientMix);
  const grain = sin(
    backdropUv.x.mul(173.0).add(backdropUv.y.mul(127.0))
  ).mul(0.009);
  backdropMaterial.colorNode = vec4(gradient.add(vec3(grain, grain, grain)), 1.0);

  const backdropGeometry = new PlaneGeometry(7, 6);
  owned.push(backdropGeometry);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const panelGeometry = new PlaneGeometry(4.1, 2.75);
  owned.push(panelGeometry);
  const panel = new Mesh(
    panelGeometry,
    makeBasicMaterial({
      color: colors.ink,
      side: DoubleSide,
    })
  );
  panel.position.set(0, 0.02, -0.12);
  root.add(panel);

  const imageGeometry = new PlaneGeometry(3.72, 2.32);
  owned.push(imageGeometry);
  const imageMaterial = makeNodeMaterial();
  imageMaterial.color.set(colors.paper);
  imageMaterial.side = DoubleSide;
  const image = new Mesh(imageGeometry, imageMaterial);
  image.position.set(0, 0.08, 0);
  root.add(image);

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        if (disposed) return;
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const shadowGeometry = new CircleGeometry(2.1, 64);
  owned.push(shadowGeometry);
  const shadow = new Mesh(
    shadowGeometry,
    makeBasicMaterial({
      color: colors.surface,
      transparent: true,
      opacity: 0.48,
      depthWrite: false,
      side: DoubleSide,
    })
  );
  shadow.scale.set(1.45, 0.36, 1);
  shadow.position.set(0, -1.43, -0.08);
  root.add(shadow);

  const accentGeometry = new BoxGeometry(1.05, 0.045, 0.055);
  owned.push(accentGeometry);
  const accent = new Mesh(
    accentGeometry,
    makeBasicMaterial({
      color: colors.accent,
      side: DoubleSide,
    })
  );
  accent.position.set(-1.22, -1.22, 0.16);
  root.add(accent);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || !ctx.fontAtlas?.createText) {
      continue;
    }

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.typography?.color ?? colors.paper,
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });

    textObject.position.set(
      item.position?.x ?? -1.55,
      item.position?.y ?? 1.15,
      item.position?.z ?? 0.2
    );
    root.add(textObject);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }
    timelines.length = 0;

    root.traverse((object) => {
      if (object.geometry && owned.includes(object.geometry)) {
        object.geometry.dispose();
      }
      if (object.material && owned.includes(object.material)) {
        object.material.dispose();
      }
    });

    owned.length = 0;
  };

  return root;
}

export default createNode;
